// ---------------------------------------------------------------
// 1. Resolve Requested Billing Period (Live Webhook + Canvas Test)
// ---------------------------------------------------------------
const webhookData = 
  $node["Webhook Trigger"]?.json || 
  $node["Webhook"]?.json || 
  $node["webhook-1790843991079001"]?.json || 
  {};

const webhookBody = webhookData.body || webhookData;
const inputItem = (typeof $input !== 'undefined' && typeof $input.first === 'function') 
  ? ($input.first()?.json || {}) 
  : {};

const requestedBillingPeriod = 
  webhookBody.billingPeriod || 
  webhookData.query?.billingPeriod || 
  inputItem.billingPeriod || 
  '';

// ---------------------------------------------------------------
// 2. Resolve Documents from Upstream "Find Document" Node
// ---------------------------------------------------------------
const docs = 
  inputItem.documents || 
  $node["Find Document"]?.json?.documents || 
  $node["mongodb.find_document-1790844000266002"]?.json?.documents || 
  [];

const availableBillingPeriods = Array.from(new Set(
  docs.map(d => d.billingPeriod).filter(Boolean)
)).sort();

// Select current month document
let doc = null;
if (requestedBillingPeriod) {
  doc = docs.find(d => d.billingPeriod === requestedBillingPeriod);
}

if (!doc && docs.length > 0) {
  const sortedDocs = [...docs].sort((a, b) => {
    const periodA = a.billingPeriod || '';
    const periodB = b.billingPeriod || '';
    if (periodA !== periodB) return periodB.localeCompare(periodA);
    const dateA = a.fetchedAt ? new Date(a.fetchedAt).getTime() : 0;
    const dateB = b.fetchedAt ? new Date(b.fetchedAt).getTime() : 0;
    return dateB - dateA;
  });
  doc = sortedDocs[0];
}

if (!doc) {
  doc = (inputItem.billingPeriod ? inputItem : {}) || {};
}

// ---------------------------------------------------------------
// 3. Find Previous Month Document for Real Comparison (e.g. Sep vs Oct)
// ---------------------------------------------------------------
const currPeriod = doc.billingPeriod || (doc.timePeriod?.start ? doc.timePeriod.start.slice(0, 7) : '2026-10');
let prevDoc = null;
if (currPeriod && /^\d{4}-\d{2}$/.test(currPeriod)) {
  const [currY, currM] = currPeriod.split('-').map(Number);
  const prevDate = new Date(currY, currM - 2, 1);
  const prevPeriodStr = `${prevDate.getFullYear()}-${String(prevDate.getMonth() + 1).padStart(2, '0')}`;
  prevDoc = docs.find(d => d.billingPeriod === prevPeriodStr);
}
if (!prevDoc && docs.length > 1) {
  prevDoc = docs.find(d => d.billingPeriod !== currPeriod) || null;
}

const prevTotalSpend = Number(prevDoc?.summary?.totalUnblendedCost || 0);
const prevDailyTotals = Array.isArray(prevDoc?.dailyTotals) ? prevDoc.dailyTotals : [];
const prevDaysCount = prevDailyTotals.length > 0 ? prevDailyTotals.length : 30;
const prevProjects = Array.isArray(prevDoc?.projectSummary) ? prevDoc.projectSummary : [];
const prevServices = Array.isArray(prevDoc?.serviceSummary) ? prevDoc.serviceSummary : [];

// ---------------------------------------------------------------
// 4. Extract Core Properties & Compute High-Level FinOps KPIs
// ---------------------------------------------------------------
const accountId = doc.accountId || '864981730114';
const accountName = doc.accountName || 'Production AWS Account';
const billingPeriod = currPeriod;
const timePeriod = doc.timePeriod || { start: `${billingPeriod}-01`, end: `${billingPeriod}-30` };

const totalSpend = Number(doc.summary?.totalUnblendedCost || 0);
const totalAmortized = Number(doc.summary?.totalAmortizedCost || totalSpend);
const currency = doc.summary?.currency || 'USD';

const dailyTotals = Array.isArray(doc.dailyTotals) ? doc.dailyTotals : [];
const serviceWiseDaily = Array.isArray(doc.serviceWiseDaily) ? doc.serviceWiseDaily : [];
const daysCount = dailyTotals.length > 0 ? dailyTotals.length : 30;
const dailyAvg = totalSpend > 0 ? Number((totalSpend / daysCount).toFixed(2)) : 0;

// Total spend comparison (Normalized Daily Run Rate)
const totalCurrDaily = totalSpend / Math.max(1, daysCount);
const totalPrevDaily = prevTotalSpend / Math.max(1, prevDaysCount);
const totalSpendChange = totalPrevDaily > 0 
  ? Math.round(((totalCurrDaily - totalPrevDaily) / totalPrevDaily) * 1000) / 10 
  : 0;

// ---------------------------------------------------------------
// 5. Enrich Projects & Services with 100% Real September Delta
// ---------------------------------------------------------------
const rawProjects = Array.isArray(doc.projectSummary) ? doc.projectSummary : [];
const projects = rawProjects.map(p => {
  const pName = p.projectName || p.project_name || 'Untagged';
  const prevP = prevProjects.find(pp => (pp.projectName || pp.project_name) === pName);
  const cost = Number(p.unblendedCost || 0);
  const prevCost = Number(prevP?.unblendedCost || 0);

  // Normalized daily rate comparison (Apples-to-apples: 5 days vs 30 days)
  const currDaily = cost / Math.max(1, daysCount);
  const prevDaily = prevCost / Math.max(1, prevDaysCount);
  const projChange = prevDaily > 0 
    ? Math.round(((currDaily - prevDaily) / prevDaily) * 1000) / 10 
    : 0;

  // Granular service level comparison inside this project
  const pServices = Array.isArray(p.services) ? p.services : [];
  const enrichedServices = pServices.map(s => {
    const prevS = prevP?.services?.find(ps => ps.service === s.service);
    const sCost = Number(s.unblendedCost || 0);
    const sPrevCost = Number(prevS?.unblendedCost || 0);
    const sCurrDaily = sCost / Math.max(1, daysCount);
    const sPrevDaily = sPrevCost / Math.max(1, prevDaysCount);
    const sChange = sPrevDaily > 0
      ? Math.round(((sCurrDaily - sPrevDaily) / sPrevDaily) * 1000) / 10
      : 0;

    return {
      ...s,
      service: s.service,
      unblendedCost: sCost,
      prevCost: sPrevCost,
      change: sChange
    };
  });

  return {
    ...p,
    projectName: pName,
    unblendedCost: cost,
    prevCost: prevCost,
    change: projChange,
    services: enrichedServices
  };
});

const rawServices = Array.isArray(doc.serviceSummary) ? doc.serviceSummary : [];
const services = rawServices.map(s => {
  const prevS = prevServices.find(ps => ps.service === s.service);
  const cost = Number(s.unblendedCost || 0);
  const prevCost = Number(prevS?.unblendedCost || 0);
  const currDaily = cost / Math.max(1, daysCount);
  const prevDaily = prevCost / Math.max(1, prevDaysCount);
  const change = prevDaily > 0 
    ? Math.round(((currDaily - prevDaily) / prevDaily) * 1000) / 10 
    : 0;

  return {
    ...s,
    service: s.service,
    unblendedCost: cost,
    prevCost,
    change
  };
});

// Top Project
const topProj = projects.find(p => (p.projectName || p.project_name) !== 'Untagged') || projects[0] || null;
const topProjName = topProj ? (topProj.projectName || topProj.project_name) : 'Agent_Builder';
const topProjCost = topProj ? Number(topProj.unblendedCost || 0) : 0;
const topProjShare = totalSpend > 0 ? Number(((topProjCost / totalSpend) * 100).toFixed(1)) : 0;

// Top Service
const topSvc = services[0] || null;
const topSvcName = topSvc?.service || 'Amazon Elastic Compute Cloud - Compute';
const topSvcCost = topSvc ? Number(topSvc.unblendedCost || 0) : 0;
const topSvcShare = totalSpend > 0 ? Number(((topSvcCost / totalSpend) * 100).toFixed(1)) : 0;

// Tag Coverage & Governance
const untaggedItem = projects.find(p => (p.projectName || p.project_name) === 'Untagged');
const untaggedSpend = untaggedItem ? Number(Number(untaggedItem.unblendedCost || 0).toFixed(2)) : 0;
const taggedSpend = Number(Math.max(0, totalSpend - untaggedSpend).toFixed(2));
const tagCoveragePercentage = totalSpend > 0 ? Number(((taggedSpend / totalSpend) * 100).toFixed(1)) : 0;

// ---------------------------------------------------------------
// 6. Generate Interactive Project x Service Heatmap Matrix
// ---------------------------------------------------------------
const topMatrixProjects = projects.slice(0, 10);
const topMatrixServices = services.slice(0, 10).map(s => s.service);

const matrixRows = topMatrixProjects.map(p => {
  const pName = p.projectName || p.project_name || 'Untagged';
  const pServices = p.services || [];
  const srvCostMap = {};

  pServices.forEach(s => {
    srvCostMap[s.service] = Number(s.unblendedCost || 0);
  });

  return {
    productId: pName,
    productName: pName,
    project: pName,
    projectName: pName,
    project_name: pName,
    services: srvCostMap,
    serviceCosts: srvCostMap,
    total: Number(p.unblendedCost || 0),
    totalCost: Number(p.unblendedCost || 0)
  };
});

const matrix = {
  services: topMatrixServices,
  rows: matrixRows
};

// ---------------------------------------------------------------
// 7. Top Cost Drivers (for Table & Cards)
// ---------------------------------------------------------------
const topCostDrivers = (doc.topCostDrivers && doc.topCostDrivers.length > 0)
  ? doc.topCostDrivers
  : projects.slice(0, 5).map(p => ({
      name: p.projectName || p.project_name,
      cost: Number(p.unblendedCost || 0),
      share: totalSpend > 0 ? Number(((Number(p.unblendedCost || 0) / totalSpend) * 100).toFixed(1)) : 0
    }));

// ---------------------------------------------------------------
// 8. Structure KPI Payload for UI
// ---------------------------------------------------------------
const kpis = {
  totalSpend,
  totalAmortized,
  currency,
  dailyAvg,
  daysCount,
  projectsCount: projects.length,
  servicesCount: services.length,
  taggedSpend,
  untaggedSpend,
  tagCoveragePercentage,
  prevTotalSpend,
  totalSpendChange,
  previousBillingPeriod: prevDoc?.billingPeriod || '2026-09',
  topProject: {
    name: topProjName,
    cost: topProjCost,
    share: topProjShare
  },
  topService: {
    name: topSvcName,
    cost: topSvcCost,
    share: topSvcShare
  }
};

// ---------------------------------------------------------------
// 9. Return Payload for Webhook Response
// ---------------------------------------------------------------
return {
  json: {
    success: true,
    source: 'agentbuilder_workflow',
    accountId,
    accountName,
    billingPeriod,
    previousBillingPeriod: prevDoc?.billingPeriod || '2026-09',
    prevTotalSpend,
    totalSpendChange,
    timePeriod,
    availableBillingPeriods,
    kpis,
    totalSpend,
    totalAmortized,
    currency,
    dailyAvg,
    daysCount,
    projectsCount: projects.length,
    servicesCount: services.length,
    taggedSpend,
    untaggedSpend,
    tagCoveragePercentage,
    topProject: kpis.topProject,
    topService: kpis.topService,
    projects,
    projectSummary: projects,
    services,
    serviceSummary: services,
    dailyTotals,
    dailyTimeline: dailyTotals,
    serviceWiseDaily,
    matrix,
    topCostDrivers,
    fetchedAt: doc.fetchedAt || new Date().toISOString()
  }
};
